def _add_g1_hand_center_eefs_to_stage(robot_prim_path: str) -> None:
    """Add hand-center rigid-body EEFs to a spawned G1 robot prim."""
    from pxr import Gf, Sdf, UsdGeom, UsdPhysics

    stage = sim_utils.get_current_stage()

    for parent_suffix, eef_name in (
        (_LEFT_HAND_CENTER_USD_PARENT.removeprefix("/Robot"), _LEFT_EEF_LINK),
        (_RIGHT_HAND_CENTER_USD_PARENT.removeprefix("/Robot"), _RIGHT_EEF_LINK),
    ):
        parent_sdf_path = Sdf.Path(f"{robot_prim_path}{parent_suffix}")
        parent_prim = stage.GetPrimAtPath(parent_sdf_path)
        if not parent_prim.IsValid():
            raise RuntimeError(f"Cannot add '{eef_name}': USD parent prim does not exist at '{parent_sdf_path}'.")

        eef_path = parent_sdf_path.AppendChild(eef_name)
        eef_xform = UsdGeom.Xform.Define(stage, eef_path)
        eef_xform.SetResetXformStack(True)
        eef_xform.AddTranslateOp().Set(Gf.Vec3d(*_HAND_CENTER_EEF_OFFSET))

        eef_prim = eef_xform.GetPrim()
        rigid_body = UsdPhysics.RigidBodyAPI.Apply(eef_prim)
        rigid_body.CreateRigidBodyEnabledAttr(True)
        UsdPhysics.MassAPI.Apply(eef_prim).CreateMassAttr(0.001)

        joint = UsdPhysics.FixedJoint.Define(stage, parent_sdf_path.AppendChild(f"{eef_name}_fixed_joint"))
        joint.CreateBody0Rel().SetTargets([parent_sdf_path])
        joint.CreateBody1Rel().SetTargets([eef_path])
        joint.CreateLocalPos0Attr(Gf.Vec3f(*_HAND_CENTER_EEF_OFFSET))
        joint.CreateLocalPos1Attr(Gf.Vec3f(0.0, 0.0, 0.0))
        joint.CreateLocalRot0Attr(Gf.Quatf(1.0, Gf.Vec3f(0.0, 0.0, 0.0)))
        joint.CreateLocalRot1Attr(Gf.Quatf(1.0, Gf.Vec3f(0.0, 0.0, 0.0)))


def _find_urdf_link_name(root: ET.Element, suffix: str, fallback: str | None = None) -> str:
    for link in root.findall("link"):
        name = link.get("name")
        if name == suffix or (name is not None and name.endswith(f"_{suffix}")):
            return name
    if fallback is not None and root.find(f"./link[@name='{fallback}']") is not None:
        return fallback
    raise ValueError(f"Could not find URDF link ending in '{suffix}'.")


def _ensure_urdf_fixed_child_link(
    root: ET.Element,
    *,
    parent_link: str,
    child_link: str,
    joint_name: str,
    xyz: tuple[float, float, float],
) -> None:
    if root.find(f"./link[@name='{child_link}']") is None:
        ET.SubElement(root, "link", {"name": child_link})

    joint = root.find(f"./joint[@name='{joint_name}']")
    if joint is None:
        joint = ET.SubElement(root, "joint", {"name": joint_name, "type": "fixed"})
    else:
        joint.set("type", "fixed")

    for tag, link_name in (("parent", parent_link), ("child", child_link)):
        elem = joint.find(tag)
        if elem is None:
            elem = ET.SubElement(joint, tag)
        elem.set("link", link_name)

    origin = joint.find("origin")
    if origin is None:
        origin = ET.SubElement(joint, "origin")
    origin.set("xyz", f"{xyz[0]:g} {xyz[1]:g} {xyz[2]:g}")
    origin.set("rpy", "0 0 0")


def _patch_g1_hand_center_eefs_into_urdf(urdf_path: str) -> None:
    """Add the same fixed hand-center EEF links to Pink's generated URDF."""
    tree = ET.parse(urdf_path)
    root = tree.getroot()

    _ensure_urdf_fixed_child_link(
        root,
        parent_link=_find_urdf_link_name(root, _LEFT_HAND_BASE_LINK, fallback=_LEFT_WRIST_YAW_URDF_LINK),
        child_link=_LEFT_EEF_URDF_FRAME,
        joint_name=f"{_LEFT_EEF_URDF_FRAME}_fixed_joint",
        xyz=_HAND_CENTER_EEF_OFFSET,
    )
    _ensure_urdf_fixed_child_link(
        root,
        parent_link=_find_urdf_link_name(root, _RIGHT_HAND_BASE_LINK, fallback=_RIGHT_WRIST_YAW_URDF_LINK),
        child_link=_RIGHT_EEF_URDF_FRAME,
        joint_name=f"{_RIGHT_EEF_URDF_FRAME}_fixed_joint",
        xyz=_HAND_CENTER_EEF_OFFSET,
    )

    ET.indent(tree, space="  ")
    tree.write(urdf_path, encoding="utf-8", xml_declaration=True)


@sim_utils.clone
def spawn_g1_with_hand_center_eefs(
    prim_path: str,
    cfg: UsdFileCfg,
    translation: tuple[float, float, float] | None = None,
    orientation: tuple[float, float, float, float] | None = None,
    **kwargs,
):
    """Spawn the Unitree G1 USD and add task-specific hand-center EEF bodies."""
    prim = sim_utils.spawn_from_usd(prim_path, cfg, translation=translation, orientation=orientation, **kwargs)
    _add_g1_hand_center_eefs_to_stage(prim_path)
    return prim


@sim_utils.clone
def spawn_rigid_usd(
    prim_path: str,
    cfg: UsdFileCfg,
    translation: tuple[float, float, float] | None = None,
    orientation: tuple[float, float, float, float] | None = None,
    **kwargs,
):
    """Spawn a visual USD and explicitly apply rigid-body APIs to its root prim."""
    rigid_props = cfg.rigid_props or sim_utils.RigidBodyPropertiesCfg()
    mass_props = cfg.mass_props or sim_utils.MassPropertiesCfg(mass=0.05)
    collision_props = cfg.collision_props or sim_utils.CollisionPropertiesCfg()
    mesh_collision_props = sim_utils.SDFMeshPropertiesCfg()

    cfg.rigid_props = None
    cfg.mass_props = None
    cfg.collision_props = None
    try:
        prim = sim_utils.spawn_from_usd(prim_path, cfg, translation=translation, orientation=orientation, **kwargs)
    finally:
        cfg.rigid_props = rigid_props
        cfg.mass_props = mass_props
        cfg.collision_props = collision_props

    sim_utils.define_rigid_body_properties(prim_path, rigid_props)
    sim_utils.define_mass_properties(prim_path, mass_props)
    sim_utils.define_collision_properties(prim_path, collision_props)
    sim_utils.define_mesh_collision_properties(prim_path, mesh_collision_props)

    leaf = prim_path.rstrip("/").rsplit("/", 1)[-1]
    mat_cfg = _PHYSICS_MATERIALS.get(leaf)
    if mat_cfg is not None:
        mat_path = f"{prim_path}/physicsMaterial"
        mat_cfg.func(mat_path, mat_cfg)
        sim_utils.bind_physics_material(prim_path, mat_path)

    color = _VISUAL_MATERIAL_COLORS.get(leaf)
    if color is not None:
        env_ns = prim_path.rstrip("/").rsplit("/", 1)[0]
        sim_utils.bind_visual_material(prim_path, f"{env_ns}/Scene/Looks/{color}")
    return prim

