# ── Subtask termination-signal parameters ──────────────────────────────────
# These dummy values are referenced from the SubtaskTermsCfg terms below.
# Tune them after recording a few demonstrations and inspecting the logged
# EEF / object trajectories.
#
# Object → arm assignment follows the initial scene layout:
#   brick_2x2   is at y = -0.2  → assigned to the RIGHT arm
#   brick_2x2_1 is at y = +0.2  → assigned to the LEFT  arm
_LEFT_BRICK = "brick_2x2_1"
_RIGHT_BRICK = "brick_2x2"
# Inspire-hand proximal joints; mean joint angle is used as a coarse
# "closed-ness" proxy. Only the thumb, index, and middle fingers are
# included — the thumb uses its pitch (curl-down) joint as the closest
# analog to the other fingers' proximal flexion.
_LEFT_GRIPPER_JOINTS = r"L_(index_proximal_joint|middle_proximal_joint|thumb_proximal_pitch_joint)"
_RIGHT_GRIPPER_JOINTS = r"R_(index_proximal_joint|middle_proximal_joint|thumb_proximal_pitch_joint)"

# Dummy thresholds — replace with values derived from real demos.
_DIST_TO_BRICK_THRESHOLD = 0.2            # m  (eef ↔ brick)
_BRICK_TO_TARGET_THRESHOLD = 0.29          # m  (brick ↔ placement target)
_GRIPPER_CLOSED_THRESHOLD = 0.5            # rad  (proximal joint mean)
_GRIPPER_OPEN_THRESHOLD = 0.15              # rad  (proximal joint mean)

# Per-arm placement targets and idle poses, in env-local frame.
_LEFT_TARGET_POS = (-0.4, 0.05, 0.83)
_RIGHT_TARGET_POS = (-0.4, -0.05, 0.83)
_LEFT_IDLE_POS = (-0.3, 0.3, 1.2)
_RIGHT_IDLE_POS = (-0.3, -0.3, 1.2)
_IDLE_BOX_HALF_EXTENT = (0.1, 0.1, 0.1)   # m  (idle pose tolerance)


@configclass
class LegoG1ObservationsCfg:
    """Observations for LegoG1."""

    @configclass
    class PolicyCfg(ObsGroup):
        actions = ObsTerm(func=mdp.last_action)
        robot_joint_pos = ObsTerm(
            func=base_mdp.joint_pos,
            params={"asset_cfg": SceneEntityCfg("robot")},
        )
        # End-effector pose observations.
        # Names MUST be `{eef_name}_eef_pos` / `{eef_name}_eef_quat` — `BaseILEnv.get_robot_eef_pose`
        # reads these out of obs_buf by that exact key when the Mimic recorder asks for EEF poses.
        left_eef_pos = ObsTerm(func=mdp.get_eef_pos, params={"link_name": _LEFT_EEF_LINK})
        left_eef_quat = ObsTerm(func=mdp.get_eef_quat, params={"link_name": _LEFT_EEF_LINK})
        right_eef_pos = ObsTerm(func=mdp.get_eef_pos, params={"link_name": _RIGHT_EEF_LINK})
        right_eef_quat = ObsTerm(func=mdp.get_eef_quat, params={"link_name": _RIGHT_EEF_LINK})

        def __post_init__(self):
            self.enable_corruption = False
            self.concatenate_terms = False

    @configclass
    class SubtaskTermsCfg(ObsGroup):
        """Subtask termination signals consumed by the annotated-teleop recorder.

        Each term returns a ``(num_envs, 1)`` binary float tensor that is ``1`` when
        the corresponding subtask is complete. ``BaseILEnv.get_subtask_term_predicates``
        reads this group out of ``obs_buf["subtask_terms"]`` and feeds it to the
        recorder's dwell-and-latch logic. The attribute names below must match the
        ``subtask_term_signal`` values declared in ``lego_g1_mimic_cfg.py``.
        """

        # ── LEFT arm subtasks ─────────────────────────────────────────────
        grasp_brick_left = ObsTerm(
            func=mdp.grasp_brick_done,
            params={
                "signal_name": "grasp_brick_left",
                "eef_link": _LEFT_EEF_LINK,
                "object_name": _LEFT_BRICK,
                "dist_threshold": _DIST_TO_BRICK_THRESHOLD,
                "gripper_joint_pattern": _LEFT_GRIPPER_JOINTS,
                "gripper_closed_threshold": _GRIPPER_CLOSED_THRESHOLD,
            },
        )
        move_brick_left = ObsTerm(
            func=mdp.move_brick_done,
            params={
                "signal_name": "move_brick_left",
                "eef_link": _LEFT_EEF_LINK,
                "object_name": _LEFT_BRICK,
                "target_pos": _LEFT_TARGET_POS,
                "eef_dist_threshold": _DIST_TO_BRICK_THRESHOLD,
                "target_dist_threshold": _BRICK_TO_TARGET_THRESHOLD,
                "gripper_joint_pattern": _LEFT_GRIPPER_JOINTS,
                "gripper_closed_threshold": _GRIPPER_CLOSED_THRESHOLD,
            },
        )
        release_brick_left = ObsTerm(
            func=mdp.release_brick_done,
            params={
                "signal_name": "release_brick_left",
                "object_name": _LEFT_BRICK,
                "target_pos": _LEFT_TARGET_POS,
                "target_dist_threshold": _BRICK_TO_TARGET_THRESHOLD,
                "gripper_joint_pattern": _LEFT_GRIPPER_JOINTS,
                "gripper_open_threshold": _GRIPPER_OPEN_THRESHOLD,
            },
        )
        idle_left = ObsTerm(
            func=mdp.idle_done,
            params={
                "signal_name": "idle_left",
                "eef_link": _LEFT_EEF_LINK,
                "idle_pos": _LEFT_IDLE_POS,
                "threshold": _IDLE_BOX_HALF_EXTENT,
            },
        )

        # ── RIGHT arm subtasks ────────────────────────────────────────────
        grasp_brick_right = ObsTerm(
            func=mdp.grasp_brick_done,
            params={
                "signal_name": "grasp_brick_right",
                "eef_link": _RIGHT_EEF_LINK,
                "object_name": _RIGHT_BRICK,
                "dist_threshold": _DIST_TO_BRICK_THRESHOLD,
                "gripper_joint_pattern": _RIGHT_GRIPPER_JOINTS,
                "gripper_closed_threshold": _GRIPPER_CLOSED_THRESHOLD,
            },
        )
        move_brick_right = ObsTerm(
            func=mdp.move_brick_done,
            params={
                "signal_name": "move_brick_right",
                "eef_link": _RIGHT_EEF_LINK,
                "object_name": _RIGHT_BRICK,
                "target_pos": _RIGHT_TARGET_POS,
                "eef_dist_threshold": _DIST_TO_BRICK_THRESHOLD,
                "target_dist_threshold": _BRICK_TO_TARGET_THRESHOLD,
                "gripper_joint_pattern": _RIGHT_GRIPPER_JOINTS,
                "gripper_closed_threshold": _GRIPPER_CLOSED_THRESHOLD,
            },
        )
        release_brick_right = ObsTerm(
            func=mdp.release_brick_done,
            params={
                "signal_name": "release_brick_right",
                "object_name": _RIGHT_BRICK,
                "target_pos": _RIGHT_TARGET_POS,
                "target_dist_threshold": _BRICK_TO_TARGET_THRESHOLD,
                "gripper_joint_pattern": _RIGHT_GRIPPER_JOINTS,
                "gripper_open_threshold": _GRIPPER_OPEN_THRESHOLD,
            },
        )
        idle_right = ObsTerm(
            func=mdp.idle_done,
            params={
                "signal_name": "idle_right",
                "eef_link": _RIGHT_EEF_LINK,
                "idle_pos": _RIGHT_IDLE_POS,
                "threshold": _IDLE_BOX_HALF_EXTENT,
            },
        )

        def __post_init__(self):
            self.enable_corruption = False
            self.concatenate_terms = False

    policy: PolicyCfg = PolicyCfg()
    subtask_terms: SubtaskTermsCfg = SubtaskTermsCfg()


# =====================================================================
# 4) EVENTS & TERMINATIONS
# =====================================================================
@configclass
class LegoG1EventCfg:
    reset_all = EventTerm(func=mdp.reset_scene_to_default, mode="reset")


@configclass
class LegoG1TerminationsCfg:
    time_out = DoneTerm(func=mdp.time_out, time_out=True)


# =====================================================================
# 5) FINAL CONFIG
# =====================================================================
@configclass
class LegoG1TaskCfg(BaseILEnvCfg):

    scene: LegoG1SceneCfg = LegoG1SceneCfg(
        num_envs=1, env_spacing=2.5, replicate_physics=True
    )
    observations: LegoG1ObservationsCfg = LegoG1ObservationsCfg()
    actions: LegoG1ActionsCfg = LegoG1ActionsCfg()
    events: LegoG1EventCfg = LegoG1EventCfg()
    terminations: LegoG1TerminationsCfg = LegoG1TerminationsCfg()

    xr: XrCfg = XrCfg(
        anchor_pos=(-1.05, 0.0, -0.3),
        anchor_rot=(1.0, 0.0, 0.0, 0.0),
    )

    NUM_OPENXR_HAND_JOINTS = 26

    def __post_init__(self):
        # EEF list — picked up by BaseILEnv methods and wired into the
        # recorder's entity_order by BaseILEnvCfg.__post_init__. Set before
        # super() so the base post-init sees it.
        self.eef_names = ["left", "right"]

        # Pink IK action tensor layout (per `_extract_controlled_frame_poses`):
        #   [L_pos(3), L_quat(4), R_pos(3), R_quat(4), hand_joints(num_hand_joints)]
        # Frame-task order follows `variable_input_tasks` in the controller cfg,
        # which here is left, then right.
        self.eef_action_slices = {
            "left":  {"pos": (0, 3),  "quat": (3, 7)},
            "right": {"pos": (7, 10), "quat": (10, 14)},
        }

        # Per-arm finger-joint column indices. Inspire hand interleaves L/R in
        # `hand_joint_names`, so the gripper slice for each arm is a *list of
        # indices* rather than a contiguous range. Derive it from the actual
        # joint name order so reordering the YAML stays correct.
        _pose_offset = 14  # 2 frame tasks * (3 + 4)
        _hand_names = self.actions.pink_ik_cfg.hand_joint_names
        self.eef_gripper_slices = {
            "left":  [_pose_offset + i for i, n in enumerate(_hand_names) if n.startswith("L_")],
            "right": [_pose_offset + i for i, n in enumerate(_hand_names) if n.startswith("R_")],
        }

        super().__post_init__()

        # Episode duration in seconds. Combined with `terminations.time_out`,
        # this causes ManagerBasedRLEnv to reset the env once this many seconds
        # of sim time have elapsed.
        self.episode_length_s = 30.0

        # Cameras — attached to robot links. Note: when running under XR teleop,
        # IsaacLab's `remove_camera_configs` strips these before scene build; the
        # bundled teleop script re-adds them via `attach_cameras` below.
        attach_cameras(self.scene)

        # Add hand-center EEF bodies in the spawned USD stage, then mirror them
        # into the generated URDF so observations and Pink IK use the same frames.
        self.scene.robot.spawn.func = spawn_g1_with_hand_center_eefs

        # Convert the original Unitree USD to URDF for Pink IK. The task-local
        # EEF links are patched into the URDF after conversion.
        temp_urdf_output_path, temp_urdf_meshes_output_path = ControllerUtils.convert_usd_to_urdf(
            self.scene.robot.spawn.usd_path, self.temp_urdf_dir, force_conversion=True
        )
        _patch_g1_hand_center_eefs_into_urdf(temp_urdf_output_path)
        self.actions.pink_ik_cfg.controller.urdf_path = temp_urdf_output_path
        self.actions.pink_ik_cfg.controller.mesh_path = temp_urdf_meshes_output_path

        # Teleop devices
        self.teleop_devices = DevicesCfg(
            devices={
                "handtracking": OpenXRDeviceCfg(
                    retargeters=[
                        UnitreeG1RetargeterCfg(
                            enable_visualization=True,
                            num_open_xr_hand_joints=2 * self.NUM_OPENXR_HAND_JOINTS,
                            sim_device=self.sim.device,
                            hand_joint_names=self.actions.pink_ik_cfg.hand_joint_names,
                        ),
                    ],
                    sim_device=self.sim.device,
                    xr_cfg=self.xr,
                ),
            }
        )
